contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 id) public {
        // Setup: grant the test contract the roles needed to schedule and execute.
        // The test contract is the Timelock admin and holds TIMELOCK_ADMIN_ROLE.
        // Grant PROPOSER_ROLE and EXECUTOR_ROLE to this contract.
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.grantRole(c.EXECUTOR_ROLE(), address(this));

        // Schedule an operation with minDelay = 0 so it is immediately ready.
        c.schedule(address(this), 0, "", bytes32(0), id, 0);

        // Read timestamp after scheduling; isOperationDone must be false.
        uint256 tsAfterSchedule = c.getTimestamp(id);
        bool doneAfterSchedule = c.isOperationDone(id);

        // Execute the operation; this should set the timestamp to _DONE_TIMESTAMP (1).
        c.execute(address(this), 0, "", bytes32(0), id);

        // Read timestamp and the done flag after execution.
        uint256 tsAfterExecute = c.getTimestamp(id);
        bool doneAfterExecute = c.isOperationDone(id);

        // General rule: isOperationDone(id) is true exactly when the stored timestamp equals 1 (the DONE marker).
        // After scheduling (timestamp = block.timestamp + 0), done must be false unless block.timestamp + 0 == 1.
        // After execution, timestamp is set to 1, so done must be true.
        assert(
            doneAfterSchedule == (tsAfterSchedule == 1) &&
            doneAfterExecute == (tsAfterExecute == 1) &&
            doneAfterExecute
        );
    }

    receive() external payable {}
}

